import jax.numpy as jnp

PARAMS = {
    "side_bias": (-3.0, 3.0),        # a fixed preference for the right side, in logits
    "stickiness": (-1.0, 6.0),       # weight of the choice trace, in logits
    "learn_rate": (0.0, 1.0),        # value learning rate (also forgetting of unchosen side)
    "beta": (0.0, 10.0),             # inverse temperature on value difference
    "trace_decay": (0.0, 1.0),       # update rate of the choice trace
}
N_LATENT = 3
LATENT_NAMES = ("q_left", "q_right", "choice_trace")


def init_latents(p, session):
    return jnp.zeros(3)


def predict(latents, p):
    z = (p["side_bias"] + p["beta"] * (latents[1] - latents[0])
         + p["stickiness"] * latents[2])
    return jnp.array([0.0, z])


def update(latents, choice, reward, p):
    a = p["learn_rate"]
    ql = jnp.where(choice == 0, latents[0] + a * (reward - latents[0]), latents[0] * (1.0 - a))
    qr = jnp.where(choice == 1, latents[1] + a * (reward - latents[1]), latents[1] * (1.0 - a))
    d = p["trace_decay"]
    tr = latents[2] + d * ((2.0 * choice - 1.0) - latents[2])
    return jnp.array([ql, qr, tr])
# EVOLVE-BLOCK-END

